<?php
declare(strict_types=1);
$id='CHAR(36) CHARACTER SET ascii COLLATE ascii_bin';
$sql=[
"CREATE TABLE domain_registrar_accounts (id $id PRIMARY KEY,provider VARCHAR(24) CHARACTER SET ascii NOT NULL CHECK(provider IN ('resellerclub','domainnameapi')),environment VARCHAR(8) CHARACTER SET ascii NOT NULL CHECK(environment='mock'),credential_ref $id NULL,enabled BOOLEAN NOT NULL DEFAULT FALSE,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6)) ENGINE=InnoDB",
"CREATE TABLE domain_tlds (name VARCHAR(189) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6)) ENGINE=InnoDB",
"CREATE TABLE domain_tld_provider_rules (id $id PRIMARY KEY,tld VARCHAR(189) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,account_id $id NOT NULL,version BIGINT UNSIGNED NOT NULL,policy_json LONGTEXT NOT NULL CHECK(JSON_VALID(policy_json)),created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_domain_rule(tld,account_id,version),FOREIGN KEY(tld) REFERENCES domain_tlds(name),FOREIGN KEY(account_id) REFERENCES domain_registrar_accounts(id)) ENGINE=InnoDB",
"CREATE TABLE domains (id $id PRIMARY KEY,service_id $id NOT NULL UNIQUE,customer_id $id NOT NULL,name_ascii VARCHAR(253) CHARACTER SET ascii COLLATE ascii_bin NOT NULL UNIQUE,tld VARCHAR(189) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,rule_id $id NOT NULL,status VARCHAR(24) CHARACTER SET ascii NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','REGISTERING','REGISTERED','TRANSFERRING','RENEWING','UNKNOWN','FAILED','EXPIRED','GRACE','REDEMPTION','TERMINATED')),provider_external_id VARCHAR(128) CHARACTER SET ascii COLLATE ascii_bin NULL,expires_at DATETIME(6) NULL,locked BOOLEAN NULL,privacy_enabled BOOLEAN NULL,version BIGINT UNSIGNED NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),KEY ix_domain_owner(customer_id,status,id),KEY ix_domain_expiry(status,expires_at,id),FOREIGN KEY(service_id) REFERENCES svc_services(id),FOREIGN KEY(customer_id) REFERENCES identity_customers(id),FOREIGN KEY(tld) REFERENCES domain_tlds(name),FOREIGN KEY(rule_id) REFERENCES domain_tld_provider_rules(id)) ENGINE=InnoDB",
"CREATE TABLE domain_contacts (id $id PRIMARY KEY,domain_id $id NOT NULL,customer_id $id NOT NULL,role VARCHAR(16) CHARACTER SET ascii NOT NULL CHECK(role IN ('REGISTRANT','ADMIN','TECH','BILLING')),version BIGINT UNSIGNED NOT NULL,contact_encrypted LONGTEXT NOT NULL,fingerprint CHAR(64) CHARACTER SET ascii NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_domain_contact(domain_id,role,version),FOREIGN KEY(domain_id) REFERENCES domains(id),FOREIGN KEY(customer_id) REFERENCES identity_customers(id)) ENGINE=InnoDB",
"CREATE TABLE domain_nameserver_snapshots (id $id PRIMARY KEY,domain_id $id NOT NULL,version BIGINT UNSIGNED NOT NULL,nameservers_json LONGTEXT NOT NULL CHECK(JSON_VALID(nameservers_json)),created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),UNIQUE KEY uq_domain_ns(domain_id,version),FOREIGN KEY(domain_id) REFERENCES domains(id)) ENGINE=InnoDB",
"CREATE TABLE domain_history (id $id PRIMARY KEY,domain_id $id NOT NULL,customer_id $id NOT NULL,kind VARCHAR(32) CHARACTER SET ascii NOT NULL,actor_id VARCHAR(64) CHARACTER SET ascii NOT NULL,trace_id $id NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT UTC_TIMESTAMP(6),KEY ix_domain_history(domain_id,created_at,id),FOREIGN KEY(domain_id) REFERENCES domains(id)) ENGINE=InnoDB",
"CREATE TRIGGER domain_identity_immutable BEFORE UPDATE ON domains FOR EACH ROW BEGIN IF OLD.service_id<>NEW.service_id OR OLD.name_ascii<>NEW.name_ascii OR OLD.tld<>NEW.tld OR OLD.customer_id<>NEW.customer_id THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable domain identity'; END IF; END",
];
foreach(['domain_tld_provider_rules','domain_contacts','domain_nameserver_snapshots','domain_history'] as $table){foreach(['UPDATE','DELETE'] as $verb){$sql[]="CREATE TRIGGER {$table}_".strtolower($verb)." BEFORE $verb ON $table FOR EACH ROW SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Immutable domain history'";}}
return $sql;
